using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Update the data file in StreamingAssets for persistence
        string filePath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");

        if (File.Exists(filePath))
        {
            string jsonContent = File.ReadAllText(filePath);
            JArray students = JArray.Parse(jsonContent);
            bool dataUpdated = false;

            foreach (var student in students)
            {
                if (student["student_id"] != null && student["student_id"].ToString() == "S001")
                {
                    student["math_score"] = 90;
                    dataUpdated = true;
                    break;
                }
            }

            if (dataUpdated)
            {
                File.WriteAllText(filePath, students.ToString());
            }
        }

        // 2. Update the visualization in the scene
        GameObject chartObj = GameObject.Find("MathScoreChart");
        if (chartObj != null)
        {
            BarChart barChart = chartObj.GetComponent<BarChart>();
            if (barChart != null)
            {
                // Get the XAxis to find the index of student S001
                var xAxis = barChart.GetChartComponent<XAxis>();
                int studentIndex = -1;

                for (int i = 0; i < xAxis.data.Count; i++)
                {
                    if (xAxis.data[i] == "S001")
                    {
                        studentIndex = i;
                        break;
                    }
                }

                // If the student is found in the chart, update the value in the first series (Math Score)
                if (studentIndex != -1)
                {
                    // UpdateData(seriesIndex, dataIndex, value)
                    barChart.UpdateData(0, studentIndex, 90.00f);
                }
                else
                {
                    Debug.LogWarning("Student S001 not found in MathScoreChart X-axis data.");
                }
            }
            else
            {
                Debug.LogError("BarChart component not found on MathScoreChart.");
            }
        }
        else
        {
            Debug.LogError("GameObject 'MathScoreChart' not found in the scene.");
        }
    }
}

