using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Define data path and view ID
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_001.json");
        string viewId = "WaterChart_Building001";

        // 2. Load the data from the streaming assets
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }
        string jsonData = File.ReadAllText(dataPath);
        JArray dataArray = JArray.Parse(jsonData);

        // 3. Find the existing chart object in the scene
        GameObject chartObj = GameObject.Find(viewId);

        // If the chart doesn't exist for some reason, create it at the scene graph position
        if (chartObj == null)
        {
            chartObj = new GameObject(viewId);
            chartObj.transform.position = new Vector3(2.00f, 3.00f, -5.00f);
            chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0.00f, 0.00f, 1.00f));

            Canvas canvas = chartObj.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            chartObj.AddComponent<CanvasScaler>();
            chartObj.AddComponent<GraphicRaycaster>();

            RectTransform rect = chartObj.GetComponent<RectTransform>();
            rect.sizeDelta = new Vector2(1.50f, 1.50f);
        }

        // 4. Get or Add the BarChart component
        BarChart chart = chartObj.GetComponent<BarChart>();
        if (chart == null)
        {
            chart = chartObj.AddComponent<BarChart>();
        }

        // 5. Configure Chart Components
        var title = chart.GetOrAddChartComponent<Title>();
        title.text = "Building 001 Water Usage";
        title.subText = "Updated at 20:00 to 120 tons";

        var xAxis = chart.GetOrAddChartComponent<XAxis>();
        xAxis.type = Axis.AxisType.Category;
        xAxis.data.Clear();

        var yAxis = chart.GetOrAddChartComponent<YAxis>();
        yAxis.type = Axis.AxisType.Value;

        chart.GetOrAddChartComponent<Legend>().show = true;
        chart.GetOrAddChartComponent<Tooltip>().show = true;

        // 6. Clear existing series and repopulate with updated data
        chart.RemoveData();
        var waterSerie = chart.AddSerie<Bar>("Water (Tons)");

        // Apply a specific color to the bars
        Color barColor;
        ColorUtility.TryParseHtmlString("#00FFFFFF", out barColor);
        waterSerie.itemStyle.color = barColor;

        foreach (var item in dataArray)
        {
            string timeLabel = item["time"].ToString();
            float waterValue;

            // Apply the user's specific update: 20:00 -> 120 tons
            if (timeLabel == "20:00")
            {
                waterValue = 120.00f;
            }
            else
            {
                waterValue = (float)item["water"];
            }

            chart.AddXAxisData(timeLabel);
            chart.AddData(0, waterValue);
        }

        // Ensure the chart is updated visually
        chart.RefreshChart();
