using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load Data
        string filePath = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_001.json");
        if (!File.Exists(filePath))
        {
            Debug.LogError("Data file not found: " + filePath);
            return;
        }

        string jsonData = File.ReadAllText(filePath);
        JArray dataArray = JArray.Parse(jsonData);

        // 2. Setup Chart Container
        string view_id = "Building001Electricity3DChart";
        GameObject chartParent = new GameObject(view_id);

        // Position the chart in front of the user
        // User is at (0, 1.7, 0) looking at (0, 0, -1)
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 userForward = new Vector3(0.00f, 0.00f, -1.00f);
        Vector3 spawnPos = userPos + (userForward * 2.50f);
        spawnPos.y = 0.50f; // Place base near floor level

        chartParent.transform.position = spawnPos;
        // Rotate to face the user (user is at 0,0,0 looking -Z, so chart faces +Z)
        chartParent.transform.rotation = Quaternion.LookRotation(new Vector3(0.00f, 0.00f, 1.00f));

        // 3. Create Title (using XCharts Title component style on a Canvas)
        GameObject canvasObj = new GameObject("ChartTitleCanvas");
        canvasObj.transform.SetParent(chartParent.transform);
        Canvas canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvasObj.transform.localPosition = new Vector3(0.00f, 2.00f, 0.00f);
        canvasObj.GetComponent<RectTransform>().sizeDelta = new Vector2(2.00f, 0.50f);

        GameObject titleObj = new GameObject("TitleText");
        titleObj.transform.SetParent(canvasObj.transform);
        Text titleText = titleObj.AddComponent<Text>();
        titleText.text = "Building 001 Electricity Usage (3D)";
        titleText.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        titleText.fontSize = 40;
        titleText.alignment = TextAnchor.MiddleCenter;
        titleText.color = ColorFromHex("#FFFFFFFF");
        titleObj.GetComponent<RectTransform>().sizeDelta = new Vector2(800f, 100f);
        titleObj.transform.localScale = new Vector3(0.005f, 0.005f, 0.005f);
        titleObj.transform.localPosition = Vector3.zero;

        // 4. Generate 3D Bars
        float barSpacing = 0.30f;
        float maxHeight = 1.50f;
        float maxVal = 2400.00f; // Based on data range provided
        int sampleCount = Mathf.Min(dataArray.Count, 15); // Show first 15 entries for clarity
        float startX = -((sampleCount - 1) * barSpacing) / 2.00f;

        for (int i = 0; i < sampleCount; i++)
        {
            var item = dataArray[i];
            float electricity = item["electricity"].Value<float>();
            string timeLabel = item["time"].ToString();

            // Create Bar
            GameObject bar = GameObject.CreatePrimitive(PrimitiveType.Cube);
            bar.name = "Bar_" + i;
            bar.transform.SetParent(chartParent.transform);

            float normalizedHeight = (electricity / maxVal) * maxHeight;
            bar.transform.localScale = new Vector3(0.20f, normalizedHeight, 0.20f);

            // Position bar so the bottom sits on the Y=0 plane of the parent
            bar.transform.localPosition = new Vector3(startX + (i * barSpacing), normalizedHeight / 2.00f, 0.00f);

            // Set Color
            Renderer renderer = bar.GetComponent<Renderer>();
            renderer.material.color = ColorFromHex("#5470C6FF");

            // Add Time Label below bar
            GameObject labelObj = new GameObject("Label_" + i);
            labelObj.transform.SetParent(chartParent.transform);
            TextMesh textMesh = labelObj.AddComponent<TextMesh>();
            textMesh.text = timeLabel;
            textMesh.fontSize = 12;
            textMesh.characterSize = 0.02f;
            textMesh.anchor = TextAnchor.UpperCenter;
            textMesh.color = ColorFromHex("#FFFFFFFF");
            labelObj.transform.localPosition = new Vector3(startX + (i * barSpacing), -0.05f, 0.00f);
            labelObj.transform.localRotation = Quaternion.Euler(0, 0, 45); // Slant for readability
        }
    }

    private static Color ColorFromHex(string hex)
    {
        if (ColorUtility.TryParseHtmlString(hex, out Color color))
        {
            return color;
        }
        return Color.white;
    }
}

