using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;

public static class GeneratedCode
{
    public static void Execute()
    {
        // Define the chart names based on the scene graph
        string[] chartNames = { "ElecChart001", "ElecChart002", "ElecChart003" };
        List<GameObject> charts = new List<GameObject>();

        // Find the chart objects in the scene
        foreach (string name in chartNames)
        {
            GameObject obj = GameObject.Find(name);
            if (obj != null)
            {
                charts.Add(obj);
            }
        }

        if (charts.Count == 0) return;

        // Grid configuration
        // Center of the grid based on the original central chart position
        Vector3 gridCenter = new Vector3(0.00f, 3.00f, -5.00f);
        float spacing = 1.60f; // Slightly larger than the 1.5m boundary size to prevent overlap
        Vector3 userPosition = new Vector3(0.00f, 1.70f, 0.00f);

        // Calculate positions for a 2x2 grid
        // Row 0 (Top), Row 1 (Bottom)
        // Col 0 (Left), Col 1 (Right)
        Vector3[] positions = new Vector3[3];
        positions[0] = gridCenter + new Vector3(-spacing / 2f, spacing / 2f, 0.00f);  // Top-Left
        positions[1] = gridCenter + new Vector3(spacing / 2f, spacing / 2f, 0.00f);   // Top-Right
        positions[2] = gridCenter + new Vector3(-spacing / 2f, -spacing / 2f, 0.00f); // Bottom-Left

        // Apply transformations
        for (int i = 0; i < charts.Count; i++)
        {
            // Set Position
            charts[i].transform.position = positions[i];

            // Set Rotation: Face the user
            // We want the forward vector of the chart to point from the chart to the user
            Vector3 directionToUser = userPosition - charts[i].transform.position;
            directionToUser.y = 0; // Keep the chart vertical
            if (directionToUser != Vector3.zero)
            {
                charts[i].transform.rotation = Quaternion.LookRotation(-directionToUser);
            }

            // Ensure scale is consistent with boundary (1.5, 1.5, 1.5)
            charts[i].transform.localScale = new Vector3(1.00f, 1.00f, 1.00f);
        }
    }
}

