using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load Data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_004.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }
        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        // 2. Create Chart Container
        string viewId = "Building004GasUsage3DScatter";
        GameObject chartObj = new GameObject(viewId);

        // 3. Calculate Position (0.3m above Building004)
        // Building004 boundary center (5.00, 2.00, -8.00), size (2.50, 4.00, 2.50)
        // Top center is at y = 4.00f. 0.3m above is 4.30f.
        Vector3 chartPos = new Vector3(5.00f, 4.30f, -8.00f);
        chartObj.transform.position = chartPos;

        // 4. Calculate Rotation (Face user at 0.00, 1.70, 0.00)
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 lookDir = userPos - chartPos;
        lookDir.y = 0.00f; // Keep the chart level horizontally
        if (lookDir != Vector3.zero)
        {
            chartObj.transform.rotation = Quaternion.LookRotation(lookDir);
        }

        // 5. Generate 3D Scatter Plot Elements
        // Mapping: X = electricity, Y = gas, Z = water
        float chartScale = 1.50f;
        float minElec = 110.00f, maxElec = 2450.00f;
        float minGas = 4.00f, maxGas = 460.00f;
        float minWater = 14.00f, maxWater = 910.00f;

        foreach (var item in data)
        {
            float e = (float)item["electricity"];
            float g = (float)item["gas"];
            float w = (float)item["water"];

            // Normalize values to 0.00f - 1.00f range
            float normX = (e - minElec) / (maxElec - minElec);
            float normY = (g - minGas) / (maxGas - minGas);
            float normZ = (w - minWater) / (maxWater - minWater);

            // Create data point sphere
            GameObject point = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            point.name = "DataPoint";
            point.transform.SetParent(chartObj.transform);

            // Position points relative to chart anchor (bottom-center)
            point.transform.localPosition = new Vector3(
                (normX - 0.50f) * chartScale,
                normY * chartScale,
                (normZ - 0.50f) * chartScale
            );

            point.transform.localScale = new Vector3(0.04f, 0.04f, 0.04f);

            // Apply Color (Cyan)
            Renderer renderer = point.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.material = new Material(Shader.Find("Standard"));
                Color pointColor;
                if (ColorUtility.TryParseHtmlString("#00FFFFFF", out pointColor))
                {
                    renderer.material.color = pointColor;
                }
            }
        }

        // 6. Add Chart Title
        GameObject titleObj = new GameObject("ChartTitle");
        titleObj.transform.SetParent(chartObj.transform);
        titleObj.transform.localPosition = new Vector3(0.00f, chartScale + 0.25f, 0.00f);
        TextMesh titleMesh = titleObj.AddComponent<TextMesh>();
        titleMesh.text = viewId;
        titleMesh.fontSize = 64;
        titleMesh.characterSize = 0.02f;
        titleMesh.anchor = TextAnchor.MiddleCenter;
        titleMesh.color = Color.white;

        // 7. Add Visual Axes
        CreateAxis(chartObj.transform, new Vector3(-0.50f, 0.00f, -0.50f) * chartScale, new Vector3(0.50f, 0.00f, -0.50f) * chartScale, "Electricity (X)");
        CreateAxis(chartObj.transform, new Vector3(-0.50f, 0.00f, -0.50f) * chartScale, new Vector3(-0.50f, 1.00f, -0.50f) * chartScale, "Gas Usage (Y)");
        CreateAxis(chartObj.transform, new Vector3(-0.50f, 0.00f, -0.50f) * chartScale, new Vector3(-0.50f, 0.00f, 0.50f) * chartScale, "Water (Z)");
    }

    private static void CreateAxis(Transform parent, Vector3 start, Vector3 end, string label)
    {
        GameObject axis = new GameObject("Axis_" + label);
        axis.transform.SetParent(parent, false);
        LineRenderer lr = axis.AddComponent<LineRenderer>();
        lr.useWorldSpace = false;
        lr.startWidth = 0.01f;
        lr.endWidth = 0.01f;
        lr.positionCount = 2;
        lr.SetPosition(0, start);
        lr.SetPosition(1, end);
        lr.material = new Material(Shader.Find("Sprites/Default"));
        lr.startColor = lr.endColor = Color.white;
    }
}

