using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Resolve pronouns and identify targets
        // "the old chart" refers to the object named "OldChart" in the scene graph.
        // "the math score chart" refers to the object named "MathScoreChart" in the scene graph.
        // "S002" is the specific data entry to be removed.

        // 2. Delete the old chart
        GameObject oldChart = GameObject.Find("OldChart");
        if (oldChart != null)
        {
            UnityEngine.Object.Destroy(oldChart);
        }

        // 3. Remove student S002 from the MathScoreChart
        GameObject mathChartObj = GameObject.Find("MathScoreChart");
        if (mathChartObj != null)
        {
            // Based on the system's default for score visualizations, we assume it's a BarChart
            BarChart chart = mathChartObj.GetComponent<BarChart>();
            if (chart != null)
            {
                // Access the XAxis to find the index of the student ID "S002"
                var xAxis = chart.GetChartComponent<XAxis>();
                if (xAxis != null)
                {
                    int indexToRemove = -1;
                    for (int i = 0; i < xAxis.data.Count; i++)
                    {
                        if (xAxis.data[i] == "S002")
                        {
                            indexToRemove = i;
                            break;
                        }
                    }

                    // If the student is found, remove the data from the axis and all series
                    if (indexToRemove != -1)
                    {
                        // Remove the label from the X-axis
                        xAxis.data.RemoveAt(indexToRemove);

                        // Remove the corresponding data point from every series (e.g., Math Score series)
                        foreach (var serie in chart.series)
                        {
                            if (indexToRemove < serie.dataCount)
                            {
                                serie.RemoveData(indexToRemove);
                            }
                        }

                        // Refresh the chart to reflect the changes in the UI
                        chart.RefreshChart();
                    }
                }
            }
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Calculate the position above Building006
        // Scene Graph Data: Building006 center at (-4.0, 1.8, -7.0) with size (2.0, 3.6, 2.0)
        // The top of the building is calculated as center.y + (size.y / 2)
        float buildingTopY = 1.80f + (3.60f / 2.0f); 
        Vector3 chartPosition = new Vector3(-4.00f, buildingTopY + 0.50f, -7.00f);

        // 2. Create the GameObject for the 3D scatter plot
        // The name "Building006GasUsage3D" serves as the descriptive view_id
        GameObject visObj = new GameObject("Building006GasUsage3D");

        // 3. Apply the requested transform: 
        // Position: 0.5m above the building
        // Rotation: 30 degrees on the Y axis
        // Scale: 80% of original (0.8f)
        visObj.transform.position = chartPosition;
        visObj.transform.rotation = Quaternion.Euler(0.00f, 30.00f, 0.00f);
        visObj.transform.localScale = new Vector3(0.80f, 0.80f, 0.80f);

        // 4. Add the DxR Vis component to handle the 3D visualization logic
        DxR.Vis vis = visObj.AddComponent<DxR.Vis>();

        // 5. Define the DxR specification in JSON format
        // We map 'time' to X, 'gas' to Y, and 'electricity' to Z to create a spatial 3D scatter plot.
        // The color is set to a constant cyan hex string (#00FFFFFF) as per the color rules.
        string spec = "{" +
            "\"data\": \"city/building_006.json\"," +
            "\"mark\": \"point\"," +
            "\"encoding\": {" +
                "\"x\": {\"field\": \"time\", \"type\": \"nominal\"}," +
                "\"y\": {\"field\": \"gas\", \"type\": \"quantitative\"}," +
                "\"z\": {\"field\": \"electricity\", \"type\": \"quantitative\"}," +
                "\"color\": {\"value\": \"#00FFFFFF\"}," +
                "\"size\": {\"value\": 20}" +
            "}" +
        "}";

        // 6. Generate the visualization using the specification string
        vis.UpdateVis(spec);
    }
}

