    {
        // User position for orientation
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);

        // Define building data and positions
        string[] buildingIds = { "Building001", "Building002" };
        string[] dataFiles = { "city/building_001.json", "city/building_002.json" };
        Vector3[] chartPositions = { new Vector3(2.00f, 1.50f, -3.80f), new Vector3(-2.00f, 1.50f, -3.80f) };

        for (int i = 0; i < buildingIds.Length; i++)
        {
            string viewId = "ElectricityUsage_" + buildingIds[i];
            string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData", dataFiles[i]);

            // Create the 3D Chart GameObject
            GameObject visObj = new GameObject(viewId);
            visObj.transform.position = chartPositions[i];
