using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load and parse the student score data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath)) return;

        string jsonData = File.ReadAllText(dataPath);
        JArray students = JArray.Parse(jsonData);

        // 2. Define shelf positions from the scene graph
        // ItemA: (-2.0, 0.5, -1.0), ItemB: (0.0, 0.5, -1.0), ItemC: (2.0, 0.5, -1.0)
        List<Vector3> shelfPositions = new List<Vector3>
        {
            new Vector3(-2.00f, 0.50f, -1.00f),
            new Vector3(0.00f, 0.50f, -1.00f),
            new Vector3(2.00f, 0.50f, -1.00f)
        };

        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);

        // 3. Create a chart for each student above their corresponding shelf
        // We limit the loop to the number of available shelves (3)
        int count = Mathf.Min(students.Count, shelfPositions.Count);

        for (int i = 0; i < count; i++)
        {
            JToken student = students[i];
            string studentId = student["student_id"].ToString();
            string studentName = student["name"].ToString();
            float mathScore = (float)student["math_score"];
            float scienceScore = (float)student["science_score"];
            float englishScore = (float)student["english_score"];

            // Create Chart Object with semantic ID
            string viewId = "StudentScoreChart_" + studentId;
            GameObject chartObj = new GameObject(viewId);

            // Setup World Space Canvas
            Canvas canvas = chartObj.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            chartObj.AddComponent<CanvasScaler>();
            chartObj.AddComponent<GraphicRaycaster>();

            // Add Bar Chart component
            BarChart chart = chartObj.AddComponent<BarChart>();
            chart.Init();

            // Configure Title
            var title = chart.GetOrAddChartComponent<Title>();
            title.text = studentName;
            title.subText = "Student ID: " + studentId;

            // Configure Axes
            var xAxis = chart.GetOrAddChartComponent<XAxis>();
            xAxis.type = Axis.AxisType.Category;
            chart.AddXAxisData("Math");
            chart.AddXAxisData("Science");
            chart.AddXAxisData("English");

            var yAxis = chart.GetOrAddChartComponent<YAxis>();
            yAxis.type = Axis.AxisType.Value;
            yAxis.minMaxType = Axis.AxisMinMaxType.Custom;
            yAxis.min = 0.00f;
            yAxis.max = 100.00f;

            // Add Data Series
            chart.RemoveData();
            var serie = chart.AddSerie<Bar>("Scores");
            serie.AddData(mathScore);
            serie.AddData(scienceScore);
            serie.AddData(englishScore);

            // Set Bar Color (using required 8-character hex format)
            Color barColor;
            if (ColorUtility.TryParseHtmlString("#5470C6FF", out barColor))
            {
                serie.itemStyle.color = barColor;
            }

            // 4. Position and Scale the chart
            // Place it 0.45m above the shelf top center (y=0.5)
            chartObj.transform.position = shelfPositions[i] + new Vector3(0.00f, 0.45f, 0.00f);

            // Scale the chart to fit the shelf width (approx 0.6m wide)
            // Default XCharts size is 400x300. 400 * 0.0015 = 0.6m.
            chartObj.transform.localScale = new Vector3(0.0015f, 0.0015f, 0.0015f);

            // Set RectTransform size
            RectTransform rect = chartObj.GetComponent<RectTransform>();
            rect.sizeDelta = new Vector2(400.00f, 300.00f);

            // 5. Rotate to face the user
            // User is at z=0, items are at z=-1. Charts should face +z.
            Vector3 lookTarget = new Vector3(userPos.x, chartObj.transform.position.y, userPos.z);
            chartObj.transform.LookAt(lookTarget);
            chartObj.transform.Rotate(0, 180, 0); // Flip to face user correctly
        }
    }
}

